/**
 * Config plugin for seasonal app icons (NF-2.23b) — phone builds only: app.config.js
 * omits it on TV, where the module is excluded from autolinking (tvOS icons are
 * layered image stacks and Android TV launches from a banner).
 *
 * The art is generated by `scripts/generate-seasonal-icons.py` into
 * `assets/images/app-icons/<id>/` and committed; this plugin only bundles it.
 *
 * iOS (Apple: "Configuring your app to use alternate app icons"):
 *   - one `AppIcon-<id>.appiconset` per variant in the app's `Images.xcassets`
 *     (single 1024 universal image, the same format as Expo's primary AppIcon);
 *   - `ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES` + `…_INCLUDE_ALL_APPICON_ASSETS`
 *     on the **app target only** (widget / Watch / intents targets keep their own
 *     icons), so actool writes `CFBundleAlternateIcons` into the built Info.plist.
 *
 * Android (activity-alias pattern — the only public way to change a launcher icon):
 *   - the MAIN/LAUNCHER filter moves off `.MainActivity` onto `.AppIconDefault`
 *     (enabled) and one `.AppIcon<Id>` alias per variant (disabled). Every other
 *     MainActivity intent filter (deep links, OAuth return, App Links) stays where it
 *     is, so links never resolve twice and `.MainActivity` itself is never disabled;
 *   - `android.app.shortcuts` (static shortcuts / App Actions) must sit on the
 *     launcher activity, so it moves onto every alias;
 *   - adaptive icons with foreground, background and monochrome (themed icon) layers,
 *     plus a 192 px bitmap for pre-API-26 launchers.
 *
 * Register this plugin BEFORE every other plugin that edits MainActivity: Expo runs
 * mods last-registered-first, so being first means our manifest pass runs last and
 * sees every `android.app.shortcuts` entry the other plugins added.
 */
const fs = require("node:fs");
const path = require("node:path");
const {
  AndroidConfig,
  createRunOncePlugin,
  withAndroidManifest,
  withDangerousMod,
  withXcodeProject,
} = require("@expo/config-plugins");

/** Alternate icon ids, in picker order. Mirrors `APP_ICON_IDS` in `src/lib/app-icon/icons.ts`. */
const ALTERNATE_ICONS = ["ramadan", "lastTen", "eidFitr", "hajj", "eidAdha", "newYear", "ashura"];

const ICONS_DIR = path.join("assets", "images", "app-icons");
const IOS_ICON_PREFIX = "AppIcon-";
const ALIAS_PREFIX = ".AppIcon";
const DEFAULT_ALIAS = `${ALIAS_PREFIX}Default`;
const SHORTCUTS_META = "android.app.shortcuts";
const MAIN_ACTION = "android.intent.action.MAIN";
const LAUNCHER_CATEGORY = "android.intent.category.LAUNCHER";

/** `lastTen` → `LastTen` (alias suffix). */
function pascal(id) {
  return id.charAt(0).toUpperCase() + id.slice(1);
}

/** `lastTen` → `last_ten` (Android resource names are lowercase snake_case). */
function snake(id) {
  return id.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);
}

function iosIconName(id) {
  return `${IOS_ICON_PREFIX}${id}`;
}

function androidAliasName(id) {
  return `${ALIAS_PREFIX}${pascal(id)}`;
}

function androidIconResource(id) {
  return `ic_launcher_season_${snake(id)}`;
}

// ---------------------------------------------------------------- Android manifest

function isLauncherFilter(filter) {
  const actions = (filter.action ?? []).map((a) => a.$?.["android:name"]);
  const categories = (filter.category ?? []).map((c) => c.$?.["android:name"]);
  return actions.includes(MAIN_ACTION) && categories.includes(LAUNCHER_CATEGORY);
}

function launcherFilter() {
  return {
    action: [{ $: { "android:name": MAIN_ACTION } }],
    category: [{ $: { "android:name": LAUNCHER_CATEGORY } }],
  };
}

/**
 * Pure + idempotent: moves the launcher entry point from `.MainActivity` onto one
 * alias per icon. Re-running it (prebuild without --clean) rebuilds the aliases
 * from the shortcuts meta-data it already moved.
 */
function applyAppIconManifest(androidManifest, icons = ALTERNATE_ICONS) {
  const app = AndroidConfig.Manifest.getMainApplicationOrThrow(androidManifest);
  const mainActivity = AndroidConfig.Manifest.getMainActivityOrThrow(androidManifest);
  const ours = (alias) => alias.$?.["android:name"]?.startsWith(ALIAS_PREFIX);
  const previousAliases = (app["activity-alias"] ?? []).filter(ours);

  // 1. MainActivity stops being a launcher entry (deep-link filters stay).
  mainActivity["intent-filter"] = (mainActivity["intent-filter"] ?? []).flatMap((filter) => {
    if (!isLauncherFilter(filter)) return [filter];
    const category = filter.category.filter((c) => c.$?.["android:name"] !== LAUNCHER_CATEGORY);
    const onlyMain = category.length === 0 && (filter.action ?? []).length === 1 && !filter.data;
    return onlyMain ? [] : [{ ...filter, category }];
  });

  // 2. Static shortcuts follow the launcher entry onto the aliases.
  const isShortcuts = (m) => m.$?.["android:name"] === SHORTCUTS_META;
  const shortcutsMeta = [
    ...(mainActivity["meta-data"] ?? []).filter(isShortcuts),
    ...previousAliases.flatMap((alias) => (alias["meta-data"] ?? []).filter(isShortcuts)),
  ].slice(0, 1);
  if (mainActivity["meta-data"]) {
    mainActivity["meta-data"] = mainActivity["meta-data"].filter((m) => !isShortcuts(m));
    if (mainActivity["meta-data"].length === 0) delete mainActivity["meta-data"];
  }

  // 3. One alias per icon; only the default is enabled in the manifest.
  const alias = (name, enabled, icon, roundIcon) => ({
    $: {
      "android:name": name,
      "android:enabled": enabled ? "true" : "false",
      "android:exported": "true",
      "android:icon": icon,
      "android:roundIcon": roundIcon,
      "android:targetActivity": ".MainActivity",
    },
    "intent-filter": [launcherFilter()],
    ...(shortcutsMeta.length ? { "meta-data": shortcutsMeta.map((m) => ({ $: { ...m.$ } })) } : {}),
  });
  app["activity-alias"] = [
    ...(app["activity-alias"] ?? []).filter((a) => !ours(a)),
    alias(DEFAULT_ALIAS, true, "@mipmap/ic_launcher", "@mipmap/ic_launcher_round"),
    ...icons.map((id) =>
      alias(
        androidAliasName(id),
        false,
        `@mipmap/${androidIconResource(id)}`,
        `@mipmap/${androidIconResource(id)}`,
      ),
    ),
  ];
  return androidManifest;
}

/** Adaptive icon XML for one variant (`mipmap-anydpi-v26`). */
function adaptiveIconXml(id) {
  const res = androidIconResource(id);
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">',
    `    <background android:drawable="@drawable/${res}_background"/>`,
    `    <foreground android:drawable="@drawable/${res}_foreground"/>`,
    `    <monochrome android:drawable="@drawable/${res}_monochrome"/>`,
    "</adaptive-icon>",
    "",
  ].join("\n");
}

/** `[source file in assets/images/app-icons/<id>/, destination under android/app/src/main/res/]`. */
function androidResourceFiles(id) {
  const res = androidIconResource(id);
  return [
    ["android-foreground.png", `drawable-nodpi/${res}_foreground.png`],
    ["android-background.png", `drawable-nodpi/${res}_background.png`],
    ["android-monochrome.png", `drawable-nodpi/${res}_monochrome.png`],
    // Pre-API-26 launchers: the anydpi-v26 XML shadows this on newer devices.
    ["android-legacy.png", `mipmap-xxxhdpi/${res}.png`],
  ];
}

function withAndroidAppIcons(config, icons) {
  config = withAndroidManifest(config, (cfg) => {
    cfg.modResults = applyAppIconManifest(cfg.modResults, icons);
    return cfg;
  });
  return withDangerousMod(config, [
    "android",
    async (cfg) => {
      const { projectRoot, platformProjectRoot } = cfg.modRequest;
      const resDir = path.join(platformProjectRoot, "app", "src", "main", "res");
      for (const id of icons) {
        for (const [from, to] of androidResourceFiles(id)) {
          const dest = path.join(resDir, to);
          fs.mkdirSync(path.dirname(dest), { recursive: true });
          fs.copyFileSync(path.join(projectRoot, ICONS_DIR, id, from), dest);
        }
        const xmlDir = path.join(resDir, "mipmap-anydpi-v26");
        fs.mkdirSync(xmlDir, { recursive: true });
        fs.writeFileSync(path.join(xmlDir, `${androidIconResource(id)}.xml`), adaptiveIconXml(id));
      }
      return cfg;
    },
  ]);
}

// ---------------------------------------------------------------- iOS

/** `Contents.json` of a single-size (Xcode 14+) universal app icon set. */
function appIconSetContents() {
  return {
    images: [{ filename: "icon.png", idiom: "universal", platform: "ios", size: "1024x1024" }],
    info: { author: "expo", version: 1 },
  };
}

/** Pure: build settings that make actool compile + declare the alternate icons. */
function applyAlternateIconBuildSettings(buildSettings, icons = ALTERNATE_ICONS) {
  buildSettings.ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES = JSON.stringify(
    icons.map(iosIconName).join(" "),
  );
  buildSettings.ASSETCATALOG_COMPILER_INCLUDE_ALL_APPICON_ASSETS = "YES";
  return buildSettings;
}

function trimQuotes(value) {
  return String(value ?? "").replace(/^"(.*)"$/, "$1");
}

/** Every build configuration of the app target (matched by name, not product type — the Watch app is an application too). */
function appTargetBuildConfigurations(project, projectName) {
  const targets = Object.entries(project.pbxNativeTargetSection()).filter(
    ([key]) => !key.endsWith("_comment"),
  );
  const app = targets.find(([, target]) => trimQuotes(target.name) === projectName);
  if (!app) throw new Error(`munib-app-icon: no Xcode target named "${projectName}"`);
  const list = project.pbxXCConfigurationList()[app[1].buildConfigurationList];
  const ids = new Set((list?.buildConfigurations ?? []).map((c) => c.value));
  return Object.entries(project.pbxXCBuildConfigurationSection())
    .filter(([key]) => ids.has(key))
    .map(([, cfg]) => cfg);
}

function withIosAppIcons(config, icons) {
  config = withDangerousMod(config, [
    "ios",
    async (cfg) => {
      const { projectRoot, platformProjectRoot, projectName } = cfg.modRequest;
      const catalog = path.join(platformProjectRoot, projectName, "Images.xcassets");
      for (const id of icons) {
        const setDir = path.join(catalog, `${iosIconName(id)}.appiconset`);
        fs.mkdirSync(setDir, { recursive: true });
        fs.copyFileSync(
          path.join(projectRoot, ICONS_DIR, id, "icon.png"),
          path.join(setDir, "icon.png"),
        );
        fs.writeFileSync(
          path.join(setDir, "Contents.json"),
          `${JSON.stringify(appIconSetContents(), null, 2)}\n`,
        );
      }
      return cfg;
    },
  ]);
  return withXcodeProject(config, (cfg) => {
    const projectName = cfg.modRequest.projectName;
    for (const buildConfig of appTargetBuildConfigurations(cfg.modResults, projectName)) {
      if (!buildConfig.buildSettings) continue;
      applyAlternateIconBuildSettings(buildConfig.buildSettings, icons);
    }
    return cfg;
  });
}

function withMunibAppIcon(config, props) {
  const icons = props?.icons ?? ALTERNATE_ICONS;
  config = withAndroidAppIcons(config, icons);
  return withIosAppIcons(config, icons);
}

module.exports = createRunOncePlugin(withMunibAppIcon, "munib-app-icon", "1.0.0");
module.exports.ALTERNATE_ICONS = ALTERNATE_ICONS;
module.exports.ICONS_DIR = ICONS_DIR;
module.exports.applyAppIconManifest = applyAppIconManifest;
module.exports.applyAlternateIconBuildSettings = applyAlternateIconBuildSettings;
module.exports.appTargetBuildConfigurations = appTargetBuildConfigurations;
module.exports.adaptiveIconXml = adaptiveIconXml;
module.exports.androidResourceFiles = androidResourceFiles;
module.exports.androidAliasName = androidAliasName;
module.exports.androidIconResource = androidIconResource;
module.exports.iosIconName = iosIconName;
module.exports.appIconSetContents = appIconSetContents;
